head.script:
scwin.screenId = "uldmgt50310";

///////// 1. 변수 및 선언 영역 /////////

scwin.lawDiv = $c.util.getComponent('lawDiv');

scwin.addruleDiv = $c.util.getComponent('addruleDiv');


///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "c_when_58", fn: function(){ return ((dlt_disclosureLawItems.getCellData(0, "lawItmStepTpNo") ?? (() => { throw new Error("unresolved:" + "disclosureLawItem.lawItmStepTpNo"); })()) == 1); } }, { id: "c_when_60", fn: function(){ return ((dlt_disclosureLawItems.getCellData(0, "lawItmStepTpNo") ?? (() => { throw new Error("unresolved:" + "disclosureLawItem.lawItmStepTpNo"); })()) == 2); } }, { id: "c_when_62", fn: function(){ return ((dlt_disclosureLawItems.getCellData(0, "lawItmStepTpNo") ?? (() => { throw new Error("unresolved:" + "disclosureLawItem.lawItmStepTpNo"); })()) == 3); } }, { id: "c_when_64", fn: function(){ return ((dlt_disclosureLawItems.getCellData(0, "lawItmStepTpNo") ?? (() => { throw new Error("unresolved:" + "disclosureLawItem.lawItmStepTpNo"); })()) == 4); } }, { id: "c_when_66", fn: function(){ return ((dlt_disclosureLawItems.getCellData(0, "lawItmStepTpNo") ?? (() => { throw new Error("unresolved:" + "disclosureLawItem.lawItmStepTpNo"); })()) == 5); } }, { id: "c_when_68", fn: function(){ return ((dlt_disclosureLawItems.getCellData(0, "lawItmStepTpNo") ?? (() => { throw new Error("unresolved:" + "disclosureLawItem.lawItmStepTpNo"); })()) == 6); } }, { id: "c_when_70", fn: function(){ return ((dlt_disclosureLawItems.getCellData(0, "lawItmStepTpNo") ?? (() => { throw new Error("unresolved:" + "disclosureLawItem.lawItmStepTpNo"); })()) == 7); } }, { id: "c_when_72", fn: function(){ return ((dlt_disclosureLawItems.getCellData(0, "lawItmStepTpNo") ?? (() => { throw new Error("unresolved:" + "disclosureLawItem.lawItmStepTpNo"); })()) == 8); } }, { id: "c_when_74", fn: function(){ return ((dlt_disclosureLawItems.getCellData(0, "lawItmStepTpNo") ?? (() => { throw new Error("unresolved:" + "disclosureLawItem.lawItmStepTpNo"); })()) == 9); } }, { id: "c_otherwise_76", fn: function(){ return (!(((dlt_disclosureLawItems.getCellData(0, "lawItmStepTpNo") ?? (() => { throw new Error("unresolved:" + "disclosureLawItem.lawItmStepTpNo"); })()) == 1) || ((dlt_disclosureLawItems.getCellData(0, "lawItmStepTpNo") ?? (() => { throw new Error("unresolved:" + "disclosureLawItem.lawItmStepTpNo"); })()) == 2) || ((dlt_disclosureLawItems.getCellData(0, "lawItmStepTpNo") ?? (() => { throw new Error("unresolved:" + "disclosureLawItem.lawItmStepTpNo"); })()) == 3) || ((dlt_disclosureLawItems.getCellData(0, "lawItmStepTpNo") ?? (() => { throw new Error("unresolved:" + "disclosureLawItem.lawItmStepTpNo"); })()) == 4) || ((dlt_disclosureLawItems.getCellData(0, "lawItmStepTpNo") ?? (() => { throw new Error("unresolved:" + "disclosureLawItem.lawItmStepTpNo"); })()) == 5) || ((dlt_disclosureLawItems.getCellData(0, "lawItmStepTpNo") ?? (() => { throw new Error("unresolved:" + "disclosureLawItem.lawItmStepTpNo"); })()) == 6) || ((dlt_disclosureLawItems.getCellData(0, "lawItmStepTpNo") ?? (() => { throw new Error("unresolved:" + "disclosureLawItem.lawItmStepTpNo"); })()) == 7) || ((dlt_disclosureLawItems.getCellData(0, "lawItmStepTpNo") ?? (() => { throw new Error("unresolved:" + "disclosureLawItem.lawItmStepTpNo"); })()) == 8) || ((dlt_disclosureLawItems.getCellData(0, "lawItmStepTpNo") ?? (() => { throw new Error("unresolved:" + "disclosureLawItem.lawItmStepTpNo"); })()) == 9))); } }, { id: "if_lawItmBystepAddNo", fn: function(){ return ((dlt_disclosureLawItems.getCellData(0, "lawItmBystepAddNo") ?? (() => { throw new Error("unresolved:" + "disclosureLawItem.lawItmBystepAddNo"); })()) > 1); } }, { id: "if_lawItmStepTpNo", fn: function(){ return ((dlt_disclosureLawItems.getCellData(0, "lawItmStepTpNo") ?? (() => { throw new Error("unresolved:" + "disclosureLawItem.lawItmStepTpNo"); })()) == 6); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
/**
 * @method
 * @name scwin.init_fillGen
 * @author Inswave
 * @date 2026. 09. 29
 * @param boxId
 * @returns
 * @hidden N
*/
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_54", entity: "dlt_disclosureLawItems", countIds: [], cells: [{ childId: "__rc1", fn: function (v, i) { return String(i + 1) + " " + String(v("lawItmTitle")) + " " + String(v("lawItmContn")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getTotalRow();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_submit). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_Insert();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_editForm = { action: "", method: 'post', target: '' };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        await scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        $c.exception.handleError(e, { context: 'uldmgt50310.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.rd_contentTp_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.rd_contentTp_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin rd_contentTp_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.changeEditMode($c.util.getComponent("rd_contentTp"))
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50310.rd_contentTp_onclick' }); }
};

/**
 * @event
 * @name scwin.img_100_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_100_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_100_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.insert()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50310.img_100_onclick' }); }
};

/**
 * @event
 * @name scwin.img_101_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_101_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_101_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.lawItemList()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50310.img_101_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_Insert
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Insert = async function () {
    const sbmOptions = {
        id: "tx_fn_Insert",
        method: "post",
        action: "/filing/updateOnlineDisclosureLaw.do",
        ref: "dma_InsertReq",
        target: "dlt_disclosureLawItems=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "uldmgt50310.tx_fn_Insert" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_preview
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_preview = async function () {
    const sbmOptions = {
        id: "tx_preview",
        method: "post",
        action: "/filing/updateDisclosureLaw.do",
        ref: "dma_previewReq",
        target: "dlt_disclosureLawItems=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "uldmgt50310.tx_preview" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.insert
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.insert = async function () {
    /* sdd-asis-lifecycle:begin fn_Insert — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_InsertReq').set('method', "updateDisclosureLawItems");
    scwin.form_editForm.action = "/filing/updateOnlineDisclosureLaw.do";
    scwin.form_editForm.target = "hiddenFrame";
    await scwin.tx_fn_Insert();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.preview
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.preview = async function () {
    /* sdd-asis-lifecycle:begin preview — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _url = "about:blank";
    const _props = "toolbar=no,menubar=no,scrollbars=yes,status=yes,resizable=yes,width=700,height=500";
    const popWin = $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), String((typeof _props !== 'undefined' ? _props : '') || '').split(',').reduce(function (o, kv) { const p = kv.split('='); const k = (p[0] || '').replace(/\s/g, ''); const v = (p[1] || '').replace(/\s/g, ''); if (k === 'width' || k === 'height') { o[k] = v; } else if (k === 'scrollbars' || k === 'resizable' || k === 'modal') { o[k] = (v === 'yes' || v === '1'); } return o; }, '' ? Object.assign({ id: "lawViewPop", scrollbars: true, resizable: true, width: "700", height: "500", type: "pageFramePopup" }, { id: '' }) : { id: "lawViewPop", scrollbars: true, resizable: true, width: "700", height: "500", type: "pageFramePopup" }), {});
    $c.util.getComponent('dma_InsertReq').set('method', "previewDisclosureLaw");
    scwin.form_editForm.action = "/filing/updateDisclosureLaw.do";
    scwin.form_editForm.target = "lawViewPop";
    await scwin.tx_preview();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.changeEditMode
 * @author Inswave
 * @date 2026. 09. 29
 * @param modeDiv
 * @returns
 * @hidden N
*/
scwin.changeEditMode = function (modeDiv) {
    /* sdd-asis-lifecycle:begin changeEditMode — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (modeDiv.getValue() === "law") {
        scwin.lawDiv.setStyle("display", "block");
        scwin.addruleDiv.setStyle("display", "none");
    } else {
        scwin.lawDiv.setStyle("display", "none");
        scwin.addruleDiv.setStyle("display", "block");
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.lawItemList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.lawItemList = function () {
    /* sdd-asis-lifecycle:begin fn_LawItemList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _url = "/filing/onlineDisclosureLaw.do?method=findDisclosureLawItemDisplay&lawNo=" + dma_disclosureLaw.get("lawNo") + "";
    goURL(_url);
    /* sdd-asis-lifecycle:end */
};
